mapper.select:
SELECT

FROM mg_course_record cr
LEFT JOIN mg_course c ON cr.course_id = c.id AND c.is_deleted = 0
LEFT JOIN mg_teacher t ON cr.teacher_id = t.id AND t.is_deleted = 0
LEFT JOIN sys_user u ON t.sys_user_id = u.id AND u.is_deleted = 0
WHERE cr.is_deleted = 0

    AND cr.course_id = #{courseId}


    AND cr.teacher_id = #{teacherId}


    AND cr.classroom_type = #{classroomType}


    AND cr.status = #{status}


    AND cr.start_time >= #{startTimeBegin}


    AND cr.start_time <= #{startTimeEnd}


    AND cr.course_name LIKE CONCAT('%', #{courseName}, '%')

ORDER BY cr.create_time DESC
